xhtml:body.xhtml:script:
(function () {
  var XHTML = "http://www.w3.org/1999/xhtml";
  var doc = document;
  function first(tag) {
    var list = doc.getElementsByTagNameNS(XHTML, tag);
    return list.length ? list[0] : null;
  }
  var body = first("body");
  var head = first("head");
  try {
    if (body) Object.defineProperty(doc, "body", { configurable: true, get: function () { return body; } });
  } catch (error) {}
  try {
    if (head) Object.defineProperty(doc, "head", { configurable: true, get: function () { return head; } });
  } catch (error) {}
  var createElement = doc.createElement.bind(doc);
  doc.createElement = function (name, options) {
    try {
      return doc.createElementNS(XHTML, name);
    } catch (error) {
      return createElement(name, options);
    }
  };
})();
